const preguntaOriginal = $json.message?.text || $json.body?.pregunta || $json.pregunta || "";
const normalizada = preguntaOriginal.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
return [{ json: {
  pregunta_original: preguntaOriginal,
  pregunta_normalizada: normalizada,
  chat_id: $json.message?.chat?.id,
  session_id: $json.body?.session_id,
  codigo_estudiante: $json.body?.codigo_estudiante,
  canal: $json.message ? "telegram" : "web"
}}];

const p = $json.pregunta_normalizada;
let intencion = "desconocido";
let respuesta_directa = null;
if (p.includes("que es el ccd") || p.includes("centro de competencias digitales")) {
  intencion = "faq_directa";
  respuesta_directa = "El Centro de Competencias Digitales, CCD, es una iniciativa institucional orientada al fortalecimiento de habilidades digitales en la comunidad universitaria, mediante cursos sobre cultura digital, analítica, contenido digital y tecnologías transformativas.";
} else if (p.includes("ruta de competencias digitales") || p.includes("competencias digitales")) {
  intencion = "faq_directa";
  respuesta_directa = "La Ruta de Competencias Digitales está organizada en tres pilares: Competencias Digitales Básicas, Analítica y Contenido Digital, y Tecnologías Transformativas.";
} else if (p.includes("cuantos cursos") || p.includes("cuantos debo tomar") || p.includes("que cursos debo tomar")) {
  intencion = "faq_directa";
  respuesta_directa = "La ruta contempla un curso obligatorio de competencias digitales básicas y cursos complementarios en Analítica y Contenido Digital y Tecnologías Transformativas.";
} else if (p.includes("insignia") || p.includes("certificacion") || p.includes("certificado")) {
  intencion = "rag_documentos";
} else if (p.includes("cuando") || p.includes("fecha") || p.includes("inscripcion") || p.includes("prueba diagnostica") || p.includes("inicio de cursos")) {
  intencion = "calendario";
} else if (p.includes("he tomado") || p.includes("mis cursos") || p.includes("historial") || p.includes("cursos realizados")) {
  intencion = "cursos_estudiante";
} else if (p.includes("noticias") || p.includes("convocatorias") || p.includes("nuevos cursos") || p.includes("novedades")) {
  intencion = "noticias";
} else if (p.includes("analitica") || p.includes("contenido digital") || p.includes("tecnologias transformativas") || p.includes("ia generativa")) {
  intencion = "oferta_cursos";
} else if (p.includes("hola") || p.includes("buenas") || p.includes("buenos dias") || p.includes("buenas tardes")) {
  intencion = "saludo";
  respuesta_directa = "Hola, soy el asistente del Centro de Competencias Digitales. Puedes preguntarme sobre cursos, calendario, ruta de competencias digitales, noticias o tu historial académico.";
}
return [{ json: { ...$json, intencion, respuesta_directa } }];

const rows = $input.all().map(i => i.json);
let texto = 'Calendario CCD:\n';
for (const r of rows) {
  texto += `- ${r.evento}: ${r.fecha_inicio || 'fecha por confirmar'}\n`;
}
return [{ json: { mensaje_respuesta: texto.trim() } }];
